import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
const loader = new GLTFLoader();
loader.load('/models/chair.glb', (gltf) => {
scene.add(gltf.scene);
// gltf.animations — AnimationClip[] (Post 06)
// gltf.cameras — Camera[] embedded in the file
// gltf.scenes — Scene[] if multiple
// gltf.userData — extras
});
Or async / Suspense-friendly:
const gltf = await loader.loadAsync('/models/chair.glb');
scene.add(gltf.scene);
GLTFLoader handles colour spaces correctly (Post 04), sets up materials, attaches animations. No manual colorSpace calls needed for textures embedded in the glTF.

